  @override
  String get legalDisclaimerRegulatoryBody =>
      'DVTech Ventures ହେଉଛି ଏକ ଟେକ୍ନୋଲୋଜି କମ୍ପାନୀ, ନିୟନ୍ତ୍ରିତ ଆଇନ ସେବା ପ୍ରଦାନକାରୀ ନୁହେଁ | ଆଇନ ସେବା ଯୋଗାଇବା ପାଇଁ ଆମେ ସଲିସିଟର୍ସ ରେଗୁଲେସନ ଅଥରିଟି (ୟୁକେ), ବାର୍ କାଉନସିଲ୍ ଅଫ୍ ଇଣ୍ଡିଆ, କେନିଆର ଲ ’ସୋସାଇଟି, କ US ଣସି ଆମେରିକୀୟ ଷ୍ଟେଟ୍ ବାର୍ କିମ୍ବା ଅନ୍ୟ କ legal ଣସି ଆଇନଗତ ନିୟାମକ ସଂସ୍ଥା ଦ୍ୱାରା ଅନୁମୋଦିତ ନୁହଁନ୍ତି। ଓମ୍ବ୍ରେଲା ପ୍ଲାଟଫର୍ମ ଲିଗାଲ୍ ସର୍ଭିସେସ୍ ଆକ୍ଟ 2007 (ୟୁକେ) କିମ୍ବା ଅନ୍ୟାନ୍ୟ ପ୍ରାଧିକରଣରେ ସମାନ ଆଇନ ଅନୁଯାୟୀ ବ୍ୟାଖ୍ୟା କରାଯାଇଥିବା ପରି ନିୟନ୍ତ୍ରିତ ଆଇନଗତ କାର୍ଯ୍ୟକଳାପ ପ୍ରଦାନ କରେ ନାହିଁ |';

  @override
