  @override
  String get legalDisclaimerRelianceBody =>
      'ଆପଣ ସ୍ ledge ୀକାର କରନ୍ତି ଯେ: (କ) ଆପଣ ନିଷ୍ପତ୍ତି ନେବାକୁ କେବଳ AI ଆଉଟପୁଟ୍ ଉପରେ ନିର୍ଭର କରିବେ ନାହିଁ ଯାହା ଆପଣଙ୍କର ଆଇନଗତ ଅଧିକାର କିମ୍ବା ବାଧ୍ୟତାମୂଳକ ଉପରେ ପ୍ରଭାବ ପକାଇବ; (ଖ) ଆଇନଗତ ପ୍ରକ୍ରିୟା ଆରମ୍ଭ କରିବା, ରକ୍ଷା କରିବା କିମ୍ବା ସମାଧାନ କରିବା ପୂର୍ବରୁ ଆପଣ ସ୍ୱାଧୀନ ଯୋଗ୍ୟ ଆଇନଗତ ପରାମର୍ଶ ଲୋଡ଼ିବେ; (ଗ) ସ୍ independent ାଧୀନ ଯାଞ୍ଚ ବିନା AI ଆଉଟପୁଟ୍ ଉପରେ ଆପଣଙ୍କର ନିର୍ଭରଶୀଳତା ହେତୁ DVTech Ventures କ harm ଣସି କ୍ଷତି ପାଇଁ ଦାୟୀ ନୁହେଁ | ଏହି ସୀମା ପ୍ରଯୁଜ୍ୟ ନିୟମ ଦ୍ୱାରା ଅନୁମୋଦିତ ପୂର୍ଣ୍ଣ ପରିମାଣରେ ପ୍ରଯୁଜ୍ୟ |';

