  @override
  String get legalDisclaimerScopeBody =>
      'ଏହି ପ୍ରତ୍ୟାଖ୍ୟାନ ଛତା ପ୍ଲାଟଫର୍ମର ପ୍ରତ୍ୟେକ ବ feature ଶିଷ୍ଟ୍ୟ ପାଇଁ ପ୍ରଯୁଜ୍ୟ, ଏଥିରେ ଅନ୍ତର୍ଭୁକ୍ତ କିନ୍ତୁ ସୀମିତ ନୁହେଁ: ଲିଗାଲ୍ ଇସୁ ଚେକର୍, ଏଇ କପିଲଟ୍, ଡକ୍ୟୁମେଣ୍ଟ୍ ସମୀକ୍ଷା, ଆଇନଗତ ଅନୁସନ୍ଧାନ, ବିଷୟ ବିଶ୍ଳେଷଣ, ରଣନୀତି ମେମୋ, ଡ୍ରାଫ୍ଟ ଡକ୍ୟୁମେଣ୍ଟ୍ ଏବଂ ଅନ୍ୟାନ୍ୟ AI ଉତ୍ପାଦିତ ବିଷୟବସ୍ତୁ | ଏହା ସମସ୍ତ ଉପଭୋକ୍ତା - ଗ୍ରାହକ, ଆଇନଜୀବୀ ଉପଭୋକ୍ତା, ଏବଂ ଆଇନ ସଂସ୍ଥା ଭିକାରୀମାନଙ୍କ ପାଇଁ ପ୍ରଯୁଜ୍ୟ - ଯେଉଁଠାରେ ଛତା କାର୍ଯ୍ୟ କରେ (ଭାରତ, ଆମେରିକା, କେନିଆ, ଏବଂ ଯୁକ୍ତରାଜ୍ୟ) |';

