  @override
  String get legalPrivacyRightsCCPABody =>
      'କାଲିଫର୍ନିଆ (CCPA / CPRA) ଅଧିକାର: ଆମେ କେଉଁ ବ୍ୟକ୍ତିଗତ ସୂଚନା ସଂଗ୍ରହ କରୁ ଜାଣିବାର ଅଧିକାର; ବିଲୋପ କରିବାର ଅଧିକାର; ବିକ୍ରୟରୁ ବାଦ୍ ଦେବାର ଅଧିକାର (ଆମେ ତଥ୍ୟ ବିକ୍ରୟ କରୁନାହୁଁ); ଅଧିକାର ବ୍ୟବହାର ପାଇଁ ଭେଦଭାବ ନ କରିବାର ଅଧିକାର; ଭୁଲ ତଥ୍ୟ ସଂଶୋଧନ କରିବାର ଅଧିକାର; ସମ୍ବେଦନଶୀଳ ବ୍ୟକ୍ତିଗତ ସୂଚନାର ବ୍ୟବହାରକୁ ସୀମିତ କରିବାର ଅଧିକାର |';

  @override
  String get legalPrivacyRightsDPDPBody =>
      'ଭାରତ DPDP ଅଧିନିୟମ ଅଧିକାର: ଆପଣଙ୍କର ଡିଜିଟାଲ୍ ବ୍ୟକ୍ତିଗତ ତଥ୍ୟକୁ ପ୍ରବେଶ, ସଂଶୋଧନ ଏବଂ ଲିଭାଇବା ଅଧିକାର; ଅଭିଯୋଗ ସମାଧାନର ଅଧିକାର; ଆପଣଙ୍କ ତରଫରୁ ଅଧିକାର ବ୍ୟବହାର କରିବାକୁ ଜଣେ ବ୍ୟକ୍ତିଙ୍କୁ ମନୋନୀତ କରିବାର ଅଧିକାର | Support@odaflow.com ରେ ଆମର ସମ୍ମତି ପରିଚାଳକ ସହିତ ଯୋଗାଯୋଗ କରନ୍ତୁ |';

  @override
  String get legalPrivacyRightsGDPRBody =>
      'GDPR / UK GDPR ଅଧିକାର (EU ଏବଂ UK ବ୍ୟବହାରକାରୀ): ପ୍ରବେଶ - ଆପଣଙ୍କର ବ୍ୟକ୍ତିଗତ ତଥ୍ୟର ଏକ କପି ପ୍ରାପ୍ତ କରନ୍ତୁ; ସଂଶୋଧନ - ଭୁଲ ତଥ୍ୟକୁ ସଠିକ୍ କରନ୍ତୁ; ଲିଭାଇବା - ବିଲୋପ ପାଇଁ ଅନୁରୋଧ (ଆଇନଗତ ଧାରଣ ଅଧୀନରେ); ପ୍ରତିବନ୍ଧକ - ଏକ ବିବାଦର ସମାଧାନ ହୋଇଥିବାବେଳେ ପ୍ରକ୍ରିୟାକରଣକୁ ସୀମିତ କରନ୍ତୁ; ପୋର୍ଟେବିଲିଟି - ଏକ ମେସିନ୍ ପଠନୀୟ ଫର୍ମାଟରେ ଆପଣଙ୍କର ତଥ୍ୟ ଗ୍ରହଣ କରନ୍ତୁ; ଆପତ୍ତି - ବ legitimate ଧ ସ୍ୱାର୍ଥ ଉପରେ ଆଧାର କରି ପ୍ରକ୍ରିୟାକରଣକୁ ବିରୋଧ; ସ୍ୱୟଂଚାଳିତ ନିଷ୍ପତ୍ତି - ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ ପ୍ରଭାବ ସହିତ କେବଳ ସ୍ୱୟଂଚାଳିତ ନିଷ୍ପତ୍ତିଗୁଡ଼ିକର ଅଧୀନ ହେବ ନାହିଁ | ଏହି ଅଧିକାରଗୁଡିକ ବ୍ୟବହାର କରିବାକୁ, support@odaflow.com କୁ ଇମେଲ୍ କରନ୍ତୁ କିମ୍ବା ଇନ୍-ଆପ୍ ଗୋପନୀୟତା ସେଟିଂସମୂହ ବ୍ୟବହାର କରନ୍ତୁ |';

