  @override
  String get legalPrivacySharingLawyerReview =>
      'ଓକିଲ ସମୀକ୍ଷା: ଯଦି ଆପଣ ଜଣେ ଓକିଲ ସମୀକ୍ଷା ପାଇଁ ଅନୁରୋଧ କରନ୍ତି, ତେବେ ଆପଣଙ୍କର କେସ୍ ସାରାଂଶ (ଯଦି ଆପଣ ଏହାକୁ ଅନୁମତି ନ ଦିଅନ୍ତି ତେବେ ସମ୍ପୂର୍ଣ୍ଣ ବିଷୟବସ୍ତୁ ନୁହେଁ) ଆମ ବଜାରରେ ନିଯୁକ୍ତ ଲାଇସେନ୍ସପ୍ରାପ୍ତ ଓକିଲଙ୍କ ସହ ଅଂଶୀଦାର ହୋଇଛି | ଯାହା ଅଂଶୀଦାର ହୋଇଛି ତାହା ତୁମେ ନିୟନ୍ତ୍ରଣ କର |';

