  @override
  String get legalStandardDisclaimer =>
      'ଛତା ଆଇନଗତ ସୂଚନା, ଡକ୍ୟୁମେଣ୍ଟ ବ୍ୟାଖ୍ୟା, ଇସୁ ପରିଚୟ ଏବଂ ବିପଦ ବିଶ୍ଳେଷଣ ପ୍ରଦାନ କରେ | ଏହା ଏକ ଆଇନ ସଂସ୍ଥା ନୁହେଁ ଏବଂ ଲାଇସେନ୍ସପ୍ରାପ୍ତ ଓକିଲଙ୍କୁ ବଦଳାଇବ ନାହିଁ | ତୁମର ପରିସ୍ଥିତି ପାଇଁ ନିର୍ଦ୍ଦିଷ୍ଟ ଆଇନଗତ ପରାମର୍ଶ ପାଇଁ, ତୁମର ଅଧିକାରରେ ଜଣେ ଯୋଗ୍ୟ ଓକିଲଙ୍କ ସହିତ ପରାମର୍ଶ କର |';

  @override
  String get legalTermsAIOutputsBody =>
      'AI ଆଉଟପୁଟଗୁଡିକ ବୃହତ ଭାଷା ମଡେଲ ଦ୍ୱାରା ସୃଷ୍ଟି ହୋଇଥାଏ ଏବଂ କେବଳ ସୂଚନାମୂଳକ ଉଦ୍ଦେଶ୍ୟରେ ପ୍ରଦାନ କରାଯାଇଥାଏ | ସେମାନେ ଆଇନଗତ ପରାମର୍ଶ ଗଠନ କରନ୍ତି ନାହିଁ, ଆଟର୍ଣ୍ଣି-କ୍ଲାଏଣ୍ଟ ସମ୍ପର୍କ ସୃଷ୍ଟି କରନ୍ତି ନାହିଁ, ଏବଂ ଜଣେ ଯୋଗ୍ୟ ଓକିଲଙ୍କ ପରାମର୍ଶର ବିକଳ୍ପ ଭାବରେ ନିର୍ଭର କରିବା ଉଚିତ୍ ନୁହେଁ | AI ଆଉଟପୁଟ୍ ଅସମ୍ପୂର୍ଣ୍ଣ, ଭୁଲ୍ କିମ୍ବା ପୁରୁଣା ହୋଇପାରେ | ନିୟମ ଏବଂ ମାମଲାଗୁଡ଼ିକର ଉକ୍ତିଗୁଡିକ ନିରପେକ୍ଷ ଭାବରେ ଯାଞ୍ଚ ହେବା ଜରୁରୀ | AI ଆଉଟପୁଟ୍ ଉପରେ ଆଧାର କରି ନିଆଯାଇଥିବା କ action ଣସି କାର୍ଯ୍ୟ ପାଇଁ ଆପଣ କେବଳ ଦାୟୀ ଅଟନ୍ତି |';

