      'ଆମେ ସମୟ ସମୟରେ ଏହି ସର୍ତ୍ତାବଳୀ ଅପଡେଟ୍ କରିପାରିବା | ସାମଗ୍ରୀକ ପରିବର୍ତ୍ତନଗୁଡିକ କାର୍ଯ୍ୟକାରୀ ହେବା ପୂର୍ବରୁ ଅତି କମରେ 30 ଦିନ ପୂର୍ବରୁ ଇମେଲ୍ ଏବଂ ଇନ୍-ଆପ୍ ବିଜ୍ଞପ୍ତି ଦ୍ୱାରା ସୂଚିତ କରାଯିବ | ପ୍ରଭାବଶାଳୀ ତାରିଖ ପରେ ଅବିରତ ବ୍ୟବହାର ଗ୍ରହଣ ଗ୍ରହଣ କରେ |';

