  @override
  String get legalTermsConfidentialityBody =>
      'ଆମେ ଆପଣଙ୍କର ବିଷୟବସ୍ତୁ ଏବଂ ବିଷୟବସ୍ତୁ ତଥ୍ୟକୁ ଗୋପନୀୟ ଭାବରେ ବ୍ୟବହାର କରୁ ଏବଂ ଆମର ଗୋପନୀୟତା ନୀତିରେ ବର୍ଣ୍ଣିତ କିମ୍ବା ଆଇନ ଅନୁଯାୟୀ ଆବଶ୍ୟକତା ବ୍ୟତୀତ ଏହାକୁ ତୃତୀୟ ପକ୍ଷଙ୍କ ନିକଟରେ ପ୍ରକାଶ କରିବୁ ନାହିଁ | ଓକିଲ ଉପଯୋଗକର୍ତ୍ତା ନିଶ୍ଚିତ ଭାବରେ କ୍ଲାଏଣ୍ଟ-ଗୋପନୀୟ ଯୋଗାଯୋଗ ପ୍ରଯୁଜ୍ୟ ବୃତ୍ତିଗତ ସୁବିଧା ନିୟମ ମାନିବା ନିଶ୍ଚିତ କରିବେ | ଭଡ଼ାଟିଆ ତଥ୍ୟକୁ ପୃଥକ କରିବା ପାଇଁ ଆମର ସିଷ୍ଟମ୍ ଗଠନ କରାଯାଇଛି |';

