      'ଆମର ତଥ୍ୟ ସଂଗ୍ରହ ଏବଂ ବ୍ୟକ୍ତିଗତ ତଥ୍ୟର ବ୍ୟବହାର ଗୋପନୀୟତା ନୀତିରେ ବର୍ଣ୍ଣନା କରାଯାଇଛି | AI ତାଲିମ ଏବଂ ଆନାଲିଟିକ୍ସ ବ୍ୟବହାର ଡାଟା ଏବଂ ଏଇ ସମ୍ମତି ନୀତିରେ ବର୍ଣ୍ଣିତ ପରି ସ୍ପଷ୍ଟ ଅପ୍ଟ-ଇନ୍ ଆବଶ୍ୟକ କରେ |';

