  @override
  String get legalTermsDefinitionsBody =>
      '\"ପ୍ଲାଟଫର୍ମ\" ର ଅର୍ଥ ହେଉଛି umbrella.okaylegal.ai ଏବଂ ସମସ୍ତ ସଂପୃକ୍ତ ପ୍ରୟୋଗ, API ଏବଂ ସେବା | \"ଗ୍ରାହକ ଉପଭୋକ୍ତା\" ଅର୍ଥାତ୍ ନିଜର ଆଇନଗତ ପରିସ୍ଥିତିକୁ ବୁ to ିବା ପାଇଁ ପ୍ଲାଟଫର୍ମ ବ୍ୟବହାର କରୁଥିବା ଜଣେ ପ୍ରାକୃତିକ ବ୍ୟକ୍ତି | \"ଓକିଲ ଉପଯୋଗକର୍ତ୍ତା\" ଅର୍ଥ ହେଉଛି ଓକିଲ OS ବ features ଶିଷ୍ଟ୍ୟ ବ୍ୟବହାର କରି ଏକ ଲାଇସେନ୍ସପ୍ରାପ୍ତ ଆଇନଗତ ବୃତ୍ତିଗତ | \"ଭିକାରୀ\" ଅର୍ଥ ଏକ ଫାର୍ମ ସବସ୍କ୍ରିପସନ୍ ସହିତ ଏକ ଆଇନ ସଂସ୍ଥା କିମ୍ବା ସଂଗଠନ | \"AI ଆଉଟପୁଟ୍\" ର ଅର୍ଥ ହେଉଛି ଯେକ Um ଣସି ପାଠ୍ୟ, ବିଶ୍ଳେଷଣ, ଡ୍ରାଫ୍ଟ, କିମ୍ବା ଆମ୍ବ୍ରେଲାର AI ସିଷ୍ଟମ୍ ଦ୍ୱାରା ଉତ୍ପନ୍ନ ସୁପାରିଶ | \"ବିଷୟ\" ଅର୍ଥ ଆଇନଜୀବୀ OS ମାଧ୍ୟମରେ ପରିଚାଳିତ ଏକ ଆଇନଗତ ମାମଲା କିମ୍ବା କାରବାର | \"DVTech Ventures\" କିମ୍ବା \"ଆମେ\" ଅର୍ଥାତ୍ ପ୍ଲାଟଫର୍ମର ଅପରେଟର୍ |';

