      'ଏହି ସର୍ତ୍ତାବଳୀ ତୁମର ଛତା ବ୍ୟବହାରକୁ ନିୟନ୍ତ୍ରଣ କରେ - DVTech Ventures ଦ୍ୱାରା ପରିଚାଳିତ AI- ଦେଶୀ ଆଇନଗତ ପ୍ଲାଟଫର୍ମ | ପ୍ଲାଟଫର୍ମର କ part ଣସି ଅଂଶ ବ୍ୟବହାର କରିବା ପୂର୍ବରୁ ଦୟାକରି ସେଗୁଡ଼ିକୁ ଭଲଭାବେ ପ read ନ୍ତୁ |';

  @override
  String get legalTermsDisputeBody =>
      'ଭାରତ ବ୍ୟବହାରକାରୀ: ଏହି ସର୍ତ୍ତାବଳୀ ଭାରତର ନିୟମ ଦ୍ୱାରା ପରିଚାଳିତ; ବେଙ୍ଗାଲୁରୁରେ ବସିଥିବା ଆର୍ବିଟ୍ରେସନ୍ ଆଣ୍ଡ କନ୍ସିଲିଏସନ୍ ଆକ୍ଟ 1996 ଅନୁଯାୟୀ ବାଧ୍ୟତାମୂଳକ ସମାଧାନ ଦ୍ୱାରା ବିବାଦର ସମାଧାନ ହେବ | ଯୁକ୍ତରାଷ୍ଟ୍ରର ଉପଭୋକ୍ତା: ଡେଲାୱେରରେ ବସିଥିବା AAA ବାଣିଜ୍ୟିକ ଆର୍ବିଟ୍ରେସନ୍ ନିୟମ ଅନୁଯାୟୀ ବାଧ୍ୟତାମୂଳକ ଆର୍ବିଟ୍ରେସନ୍ ଦ୍ୱାରା ବିବାଦର ସମାଧାନ ହେବ; ଶ୍ରେଣୀ କାର୍ଯ୍ୟ ଛାଡ ପ୍ରଯୁଜ୍ୟ | କେନିଆ ବ୍ୟବହାରକାରୀ: ଏହି ସର୍ତ୍ତାବଳୀ କେନିଆର ନିୟମ ଦ୍ୱାରା ପରିଚାଳିତ; ନାଇରୋବି ସେଣ୍ଟର ଫର ଇଣ୍ଟରନ୍ୟାସନାଲ ଆର୍ବିଟ୍ରେସନ୍ (NCIA) ନିୟମ ଅନୁଯାୟୀ ବିବାଦର ସମାଧାନ ହେବ | ଯୁକ୍ତରାଜ୍ୟ ବ୍ୟବହାରକାରୀ: ଏହି ସର୍ତ୍ତାବଳୀ ଇଂରାଜୀ ନିୟମ ଦ୍ୱାରା ପରିଚାଳିତ; ବିବାଦ ଇଂଲଣ୍ଡ ଏବଂ ୱେଲ୍ସ କୋର୍ଟର ସ୍ୱତନ୍ତ୍ର ଅଧିକାର ଅଧୀନରେ ଦାଖଲ ହେବ | ସମସ୍ତ ମାମଲାରେ, କ compet ଣସି ଦକ୍ଷ ଅଦାଲତରୁ ଜରୁରୀକାଳୀନ ରିଲିଫ୍ ମାଗିବାରେ ଆପଣଙ୍କୁ କ nothing ଣସି ପ୍ରତିବନ୍ଧକ ନାହିଁ |';

